    /* ---------- import ---------- */
    function doImport(text) { const r = W.importText(text, st.formComp || st.sel || ''); if (r.obs.length || r.meta.pageId || r.meta.advId) { const key = st.formComp || st.sel || ''; W.addMany(r.obs, key, r.meta); $('#w13PasteNote', root).textContent = `Imported: ${r.note}.`; toast(`Imported ${r.obs.length} entries`); } else $('#w13PasteNote', root).textContent = r.note; }
    $('#w13PasteGo', root).onclick = () => doImport($('#w13Paste', root).value);
    $('#w13File', root).onchange = e => { const f = e.target.files && e.target.files[0]; if (!f) return; const rd = new FileReader(); rd.onload = () => { const t = String(rd.result || ''); let j = null; try { j = JSON.parse(t); } catch (_) { } if (j && Array.isArray(j.obs) && j.meta) { W.replaceAll(j); toast(`Ledger replaced: ${j.obs.length} entries`); } else doImport(t); e.target.value = ''; }; rd.readAsText(f); };
    $('#w13Import', root).onclick = () => $('#w13File', root).click();
    /* ---------- API bridge ---------- */
    function apiOpts() { const pages = $('#w13Pages', root).value.split(/[\s,;]+/).filter(Boolean); return { token: $('#w13Tok', root).value.trim(), terms: pages.length ? '' : $('#w13Terms', root).value.trim(), pageIds: pages, adType: $('#w13Type', root).value, status: $('#w13Status', root).value, since: $('#w13Since', root).value, version: $('#w13Ver', root).value.trim() || 'v21.0', limit: +$('#w13Lim', root).value || 100, maxPages: +$('#w13Pg', root).value || 3 }; }
    function apiUrlShow() { const o = apiOpts(); if (!o.terms && !o.pageIds.length) { $('#w13Url', root).textContent = 'Enter search terms or at least one Page ID.'; $('#w13ApiNote', root).textContent = ''; $('#w13Open', root).removeAttribute('href'); return; } const u = W.metaApiUrl(o); const shown = o.token ? u.replace(o.token, o.token.slice(0, 6) + '…') : u; $('#w13Url', root).textContent = shown; $('#w13Open', root).href = u; $('#w13ApiNote', root).textContent = W.canFetch() ? (o.token ? 'This page can call the Graph API directly from here.' : 'Add a token to run, or open the URL after adding it to the query.') : 'Inside the Claude viewer the platform call is blocked; open the URL in a new tab (with the token) and paste the JSON answer into the import box.'; }
    ['w13Tok', 'w13Terms', 'w13Pages', 'w13Type', 'w13Status', 'w13Since', 'w13Ver', 'w13Lim', 'w13Pg'].forEach(id => $('#' + id, root).addEventListener('input', apiUrlShow));
