    $('#w13Keep', root).onchange = e => W.setSettings({ keepToken: e.target.checked, token: e.target.checked ? $('#w13Tok', root).value.trim() : '' });
    $('#w13Tok', root).addEventListener('change', () => { if (W.settings().keepToken) W.setSettings({ token: $('#w13Tok', root).value.trim() }); });
